/* Smooth time-off editor; availability is saved to the existing calendar block model. */
function blockClock(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function blockLabel(n){return `${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n>=720?'PM':'AM'}`;}
function blockDraft(){if(!state.blockDraft)state.blockDraft={mode:'time',from:state.calendarDate>=today?state.calendarDate:today,through:state.calendarDate>=today?state.calendarDate:today,start:720,end:750,reason:'Lunch break',barber:activeBarberId()};if(state.role==='Barber Pro')state.blockDraft.barber=activeBarberId();return state.blockDraft;}
function blockCandidates(d){if(!['full','time'].includes(d.mode)||!/^\d{4}-\d{2}-\d{2}$/.test(d.from)||iso(dateObj(d.from))!==d.from||d.from<today)throw Error('Choose today or a future date.');const through=d.mode==='full'?d.through:d.from;if(!/^\d{4}-\d{2}-\d{2}$/.test(through)||iso(dateObj(through))!==through||through<d.from)throw Error('The end date must be on or after the start date.');if(!barbers.some(b=>b.id===d.barber)||state.role==='Barber Pro'&&d.barber!==activeBarberId())throw Error('Choose a valid barber.');if(!d.reason.trim())throw Error('Add a short reason for this block.');if(d.mode==='time'&&(!Number.isInteger(d.start)||!Number.isInteger(d.end)||d.start%15||d.end%15||d.start<360||d.end>1320||d.end<=d.start))throw Error('Choose a valid time in 15-minute steps.');const dates=[];for(let date=d.from;date<=through;date=addDays(date,1)){if(dates.length===31)throw Error('Choose up to 31 days at a time.');dates.push(date);}const start=d.mode==='full'?0:d.start,end=d.mode==='full'?1439:d.end;if(dates.some(date=>bookings.some(b=>b.barber===d.barber&&b.date===date&&b.status!=='cancelled'&&minutes(b.time)<end&&minutes(b.time)+bookingDuration(b)>start)))throw Error('An appointment overlaps this block. Choose another time or reschedule the visit first.');if(dates.some(date=>extras.blocks.some(b=>(!d.editId||b.id!==d.editId)&&b.barber===d.barber&&b.date===date&&clockMinutes(b.start)<end&&clockMinutes(b.end)>start)))throw Error('Some of this time is already blocked. Remove or adjust the existing block first.');return dates.map(date=>({id:'block-'+crypto.randomUUID(),barber:d.barber,date,start:d.mode==='full'?'00:00':blockClock(start),end:d.mode==='full'?'23:59':blockClock(end),reason:d.reason.trim().slice(0,80)}));}
function blockOptions(value){return Array.from({length:65},(_,i)=>360+i*15).map(n=>`<option value="${n}" ${n===value?'selected':''}>${blockLabel(n)}</option>`).join('');}
function blockConflict(d){try{blockCandidates({...d,reason:d.reason.trim()||(d.mode==='full'?'Time off':'Break')});return '';}catch(err){return err.message;}}
function blockSummary(d){return d.mode==='full'?`Block ${pretty(d.from)}${d.through>d.from?' to '+pretty(d.through):''} · Full day`:`Block ${d.from===today?'today':pretty(d.from)} · ${blockLabel(d.start)}–${blockLabel(d.end)}`;}
function smoothBlockPage(){if(!isStaff())return head('Staff access required.','');const d=blockDraft(),blocks=extras.blocks.filter(b=>b.barber===d.barber&&b.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||clockMinutes(a.start)-clockMinutes(b.start));return `<div class="compact-block"><div class="row between"><div><small class="block-eyebrow">YOUR CALENDAR</small><h2>${d.editId?'Edit blocked time':'Block time'}</h2></div><button type="button" class="icon-btn" data-block="close" aria-label="Close block time">${icon('close')}</button></div><form id="smooth-block-form"><fieldset class="compact-block-modes"><legend class="sr-only">Block type</legend>${[['time','Time block'],['full','Full day']].map(([id,label])=>`<label><input type="radio" name="blockMode" value="${id}" ${d.mode===id?'checked':''}><span>${label}</span></label>`).join('')}</fieldset>${state.role==='Owner HQ'?`<label class="field">Barber<select name="barber">${barbers.map(b=>`<option value="${b.id}" ${b.id===d.barber?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>`:''}<div class="compact-block-fields"><label class="field">${d.mode==='full'?'From':'Date'}<input type="date" name="from" min="${today}" value="${d.from}" required></label>${d.mode==='full'?`<label class="field">Through<input type="date" name="through" min="${d.from}" value="${d.through}" required></label>`:''}</div>${d.mode==='time'?`<div class="compact-block-presets" role="group" aria-label="Duration">${[15,30,60].map(n=>`<button type="button" data-block="duration" data-minutes="${n}" aria-pressed="${d.end-d.start===n}">${n} min</button>`).join('')}<button type="button" data-block="custom" aria-pressed="${![15,30,60].includes(d.end-d.start)}">Custom</button></div><div class="compact-block-fields"><label class="field">Starts<select name="start">${blockOptions(d.start)}</select></label><label class="field">Ends<select name="end">${blockOptions(d.end)}</select></label></div><div class="compact-block-timeline" aria-label="Day preview: gray appointments, red selected block">${bookings.filter(b=>b.barber===d.barber&&b.date===d.from&&b.status!=='cancelled').map(b=>`<i title="${esc(b.client)} · ${esc(b.time)}" style="left:${Math.max(0,(minutes(b.time)-360)/960*100)}%;width:${bookingDuration(b)/960*100}%"></i>`).join('')}<b style="left:${(d.start-360)/960*100}%;width:${(d.end-d.start)/960*100}%"></b></div><div class="compact-block-scale"><span>6 AM</span><span>Appointments in gray</span><span>10 PM</span></div>`:'<p class="compact-day-note">The full day will be unavailable for new bookings.</p>'}<label class="field">Reason <small>(optional)</small><input name="reason" maxlength="80" value="${esc(d.reason)}" placeholder="Break, lunch or time off"></label><div class="compact-reasons">${['Break','Lunch','Personal','Time off'].map(reason=>`<button type="button" data-block="reason" data-reason="${reason}" aria-pressed="${reason===d.reason}">${reason}</button>`).join('')}</div><p class="connect-error" role="alert" id="smooth-block-error">${blockConflict(d)}</p><button class="btn full" type="submit" ${blockConflict(d)?'disabled':''}>${icon('check')} ${d.editId?'Save · ':''}${blockSummary(d)}</button>${d.editId?`<button class="text-btn block-delete" type="button" data-block="remove" data-id="${esc(d.editId)}">Remove this block</button>`:''}</form>${!d.editId&&blocks.length?`<details class="compact-saved"><summary>Upcoming blocks · ${blocks.length}</summary>${blocks.slice(0,8).map(b=>`<button type="button" data-block="edit" data-id="${esc(b.id)}"><span>${esc(b.reason)}<small>${pretty(b.date)} · ${b.start==='00:00'?'Full day':b.start+'–'+b.end}</small></span>${icon('chevron')}</button>`).join('')}</details>`:''}</div>`;}
const availabilityBeforeSmooth=availability;availability=function(){return isStaff()?smoothBlockPage():availabilityBeforeSmooth();};
function refreshBlockEditor(){const dialog=document.querySelector('#block-time-panel');if(dialog)dialog.innerHTML=smoothBlockPage();else render();}
function closeBlockPanel(){const dialog=document.querySelector('#block-time-panel');dialog?.close();dialog?.remove();state.blockDraft=null;}
function openBlockPanel(){if(!isStaff())return;let dialog=document.querySelector('#block-time-panel');if(dialog){refreshBlockEditor();return;}dialog=document.createElement('dialog');dialog.id='block-time-panel';dialog.className='compact-block-dialog';dialog.innerHTML=smoothBlockPage();document.body.append(dialog);dialog.addEventListener('cancel',()=>{state.blockDraft=null;dialog.remove();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeBlockPanel();}});dialog.showModal();}
const goBeforeCompactBlock=go;go=function(view){if(view==='pBlock'&&isStaff()){openBlockPanel();return;}return goBeforeCompactBlock(view);};
document.addEventListener('change',e=>{if(!e.target.closest('#smooth-block-form'))return;const d=blockDraft(),key=e.target.name;if(key==='blockMode'){d.mode=e.target.value;if(d.mode==='full'&&['Lunch break','Break','Lunch'].includes(d.reason))d.reason='Time off';}else if(key==='barber'){d.barber=e.target.value;d.editId=null;}else if(['from','through'].includes(key)){d[key]=e.target.value;if(key==='from'&&(d.through<d.from||d.mode==='time'))d.through=d.from;}else if(['start','end'].includes(key)){const length=d.end-d.start;d[key]=Number(e.target.value);if(key==='start')d.end=Math.min(1320,d.start+Math.max(15,length));if(d.start>=d.end)d.start=d.end-15;}else return;refreshBlockEditor();});
document.addEventListener('input',e=>{if(e.target.closest('#smooth-block-form')&&e.target.name==='reason')blockDraft().reason=e.target.value;});
document.addEventListener('click',e=>{const button=e.target.closest('[data-block]');if(!button||!isStaff())return;const action=button.dataset.block;if(action==='close'){closeBlockPanel();return;}if(action==='edit'){const b=extras.blocks.find(b=>b.id===button.dataset.id);if(!b||state.role==='Barber Pro'&&b.barber!==activeBarberId())return;state.blockDraft={editId:b.id,barber:b.barber,mode:b.start==='00:00'&&b.end==='23:59'?'full':'time',from:b.date,through:b.date,start:b.start==='00:00'?720:clockMinutes(b.start),end:b.end==='23:59'?750:clockMinutes(b.end),reason:b.reason};openBlockPanel();return;}const d=blockDraft();if(action==='duration'){d.start=Math.min(d.start,1320-Number(button.dataset.minutes));d.end=d.start+Number(button.dataset.minutes);}else if(action==='custom'){document.querySelector('#smooth-block-form [name=end]')?.focus();return;}else if(action==='reason'){d.reason=button.dataset.reason;}else if(action==='remove'){const b=extras.blocks.find(b=>b.id===button.dataset.id);if(!b||state.role==='Barber Pro'&&b.barber!==activeBarberId())return;extras.blocks=extras.blocks.filter(b=>b.id!==button.dataset.id);save();closeBlockPanel();render();toast('Time unblocked.');return;}else return;refreshBlockEditor();});
document.addEventListener('submit',e=>{if(e.target.id!=='smooth-block-form')return;e.preventDefault();if(!isStaff())return;try{const d=blockDraft();d.reason=d.reason.trim()||(d.mode==='full'?'Time off':'Break');if(d.editId){const original=extras.blocks.find(b=>b.id===d.editId);if(!original||state.role==='Barber Pro'&&original.barber!==activeBarberId())throw Error('This block is no longer available.');}const blocks=blockCandidates(d);extras.blocks=extras.blocks.filter(b=>b.id!==d.editId);extras.blocks.push(...blocks);state.calendarDate=d.from;state.agendaMonth=d.from.slice(0,7);save();closeBlockPanel();go(state.role==='Owner HQ'?'calendar':'pCalendar');toast('Blocked time saved.');}catch(err){document.querySelector('#smooth-block-error').textContent=err.message;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.agenda-block[data-block]')){e.preventDefault();e.target.click();}});
const renderBeforeSmoothBlock=render;render=function(){renderBeforeSmoothBlock();if(state.role==='Owner HQ'&&state.view==='calendar')document.querySelector('.page-head')?.insertAdjacentHTML('afterend',`<div class="block-owner-action"><button class="btn secondary" data-view="pBlock">${icon('clock')} Block time</button></div>`);};
render();
